dashboard.definition:
{
  "title": "Wazuh - Compliance",
  "description": "Regulatory requirements of the rules that produced the findings.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_01": {
      "type": "ds.search",
      "name": "PCI DSS findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.pci_dss{}\"=* | stats count"
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "NIST 800-53 findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.nist_800_53{}\"=* | stats count"
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "NIST 800-171 findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.nist_800_171{}\"=* | stats count"
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "GDPR findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.gdpr{}\"=* | stats count"
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "HIPAA findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.hipaa{}\"=* | stats count"
      }
    },
    "ds_06": {
      "type": "ds.search",
      "name": "ISO 27001 findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.iso_27001{}\"=* | stats count"
      }
    },
    "ds_07": {
      "type": "ds.search",
      "name": "NIS2 findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.nis2{}\"=* | stats count"
      }
    },
    "ds_08": {
      "type": "ds.search",
      "name": "TSC findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.tsc{}\"=* | stats count"
      }
    },
    "ds_09": {
      "type": "ds.search",
      "name": "CMMC findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.cmmc{}\"=* | stats count"
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "FedRAMP findings",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.fedramp{}\"=* | stats count"
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Findings by framework over time",
      "options": {
        "query": "`wazuh_findings` | eval framework=mvappend(if(isnotnull('wazuh.rule.compliance.pci_dss{}'),\"PCI DSS\",null()), if(isnotnull('wazuh.rule.compliance.nist_800_53{}'),\"NIST 800-53\",null()), if(isnotnull('wazuh.rule.compliance.nist_800_171{}'),\"NIST 800-171\",null()), if(isnotnull('wazuh.rule.compliance.gdpr{}'),\"GDPR\",null()), if(isnotnull('wazuh.rule.compliance.hipaa{}'),\"HIPAA\",null()), if(isnotnull('wazuh.rule.compliance.iso_27001{}'),\"ISO 27001\",null()), if(isnotnull('wazuh.rule.compliance.nis2{}'),\"NIS2\",null()), if(isnotnull('wazuh.rule.compliance.tsc{}'),\"TSC\",null()), if(isnotnull('wazuh.rule.compliance.cmmc{}'),\"CMMC\",null()), if(isnotnull('wazuh.rule.compliance.fedramp{}'),\"FedRAMP\",null())) | where isnotnull(framework) | timechart usenull=f useother=f limit=0 count by framework"
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "PCI DSS requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.pci_dss{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "NIST 800-53 requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.nist_800_53{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "NIST 800-171 requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.nist_800_171{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "GDPR requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.gdpr{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "HIPAA requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.hipaa{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "ISO 27001 requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.iso_27001{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "NIS2 requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.nis2{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_19": {
      "type": "ds.search",
      "name": "TSC requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.tsc{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_20": {
      "type": "ds.search",
      "name": "CMMC requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.cmmc{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_21": {
      "type": "ds.search",
      "name": "FedRAMP requirements",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.fedramp{}\" as requirement | where isnotnull(requirement) | stats count by requirement | sort - count | head 10"
      }
    },
    "ds_22": {
      "type": "ds.search",
      "name": "Requirements by rule",
      "options": {
        "query": "`wazuh_findings` | rename \"wazuh.rule.compliance.pci_dss{}\" as pci_dss, \"wazuh.rule.compliance.nist_800_53{}\" as nist_800_53, \"wazuh.rule.compliance.nist_800_171{}\" as nist_800_171, \"wazuh.rule.compliance.gdpr{}\" as gdpr, \"wazuh.rule.compliance.hipaa{}\" as hipaa, \"wazuh.rule.compliance.iso_27001{}\" as iso_27001, \"wazuh.rule.compliance.nis2{}\" as nis2, \"wazuh.rule.compliance.tsc{}\" as tsc, \"wazuh.rule.compliance.cmmc{}\" as cmmc, \"wazuh.rule.compliance.fedramp{}\" as fedramp | where isnotnull(pci_dss) OR isnotnull(nist_800_53) OR isnotnull(nist_800_171) OR isnotnull(gdpr) OR isnotnull(hipaa) OR isnotnull(iso_27001) OR isnotnull(nis2) OR isnotnull(tsc) OR isnotnull(cmmc) OR isnotnull(fedramp) | stats count, dc(wazuh.agent.name) as agents, values(pci_dss) as pci_dss, values(nist_800_53) as nist_800_53, values(nist_800_171) as nist_800_171, values(gdpr) as gdpr, values(hipaa) as hipaa, values(iso_27001) as iso_27001, values(nis2) as nis2, values(tsc) as tsc, values(cmmc) as cmmc, values(fedramp) as fedramp by wazuh.rule.title | sort - count"
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.singlevalue",
      "title": "PCI DSS findings",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {}
    },
    "viz_02": {
      "type": "splunk.singlevalue",
      "title": "NIST 800-53 findings",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {}
    },
    "viz_03": {
      "type": "splunk.singlevalue",
      "title": "NIST 800-171 findings",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {}
    },
    "viz_04": {
      "type": "splunk.singlevalue",
      "title": "GDPR findings",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {}
    },
    "viz_05": {
      "type": "splunk.singlevalue",
